require_once __DIR__.'/includes/functions.php';verify_csrf();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=post_string('name',150);$email=strtolower(post_string('email',150));$phone=post_string('phone',50);$type=post_string('inquiry_type',20);$message=post_string('message',4000);if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($type,['general','appointment'],true)||strlen($message)<10){$error='Please enter your name, valid email and a message of at least 10 characters.';}else{$s=db()->prepare('INSERT INTO inquiries(name,email,phone,inquiry_type,message) VALUES(?,?,?,?,?)');$s->execute([$name,$email,$phone,$type,$message]);flash('success','Your inquiry has been received. The clinic team will follow up.');redirect('contact.php');}}$pageTitle='Contact the clinic';require __DIR__.'/includes/header.php';require __DIR__.'/includes/page.php';page_heading('We are here to help','Contact the clinic','Send a general question or appointment inquiry.');?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body p-4"><form method="post" data-disable-submit><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" name="name" required maxlength="150"></div><div class="col-md-6"><label class="form-label">Email *</label><input class="form-control" type="email" name="email" required maxlength="150"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" maxlength="50"></div><div class="col-md-6"><label class="form-label">Inquiry type</label><select class="form-select" name="inquiry_type"><option value="general">General question</option><option value="appointment">Appointment inquiry</option></select></div><div class="col-12"><label class="form-label">Message *</label><textarea class="form-control" name="message" rows="5" minlength="10" maxlength="4000" required></textarea></div></div><button class="btn btn-primary mt-4">Send inquiry <i class="bi bi-send ms-1"></i></button></form></div></div></div><div class="col-lg-5"><div class="card h-100"><div class="card-body p-4"><div class="stat-icon mb-3"><i class="bi bi-headset"></i></div><h2 class="h5 fw-bold">Clinic contact</h2><p class="text-secondary">For appointments, general questions or help using the patient portal, send a message and our team will follow up.</p><hr><div class="d-flex gap-3 mb-3"><i class="bi bi-telephone text-success fs-5"></i><div><div class="small-muted">PHONE</div><strong><?=e(setting('clinic_phone','Contact clinic'))?></strong></div></div><div class="d-flex gap-3 mb-3"><i class="bi bi-envelope text-success fs-5"></i><div><div class="small-muted">EMAIL</div><strong><?=e(setting('clinic_email',''))?></strong></div></div><div class="d-flex gap-3"><i class="bi bi-geo-alt text-success fs-5"></i><div><div class="small-muted">ADDRESS</div><strong><?=e(setting('clinic_address',''))?></strong></div></div></div></div></div></div><?php require __DIR__.'/includes/footer.php';?>